// Apuntamos directamente a order.body
const order = items[0].json.body;
const data = order ? order : items[0].json;

let mensaje = "";
const tipoNotif = data.tipo || 'compra';

if (tipoNotif === 'alerta_cocina') {
    const mesa = data.mesa || 'Mesa';
    const total = data.total || 0;
    const mozo = data.mozo_nombre || 'Mozo';
    mensaje = `🛎️ *¡PEDIDO LISTO EN COCINA!* 👨‍🍳\n----------------------------------\n📍 *Ubicación:* ${mesa}\n👤 *Atendido por:* ${mozo}\n💰 *Monto:* S/. ${parseFloat(total).toFixed(2)}\n----------------------------------\n🏃‍♂️ _Por favor, retirar del mostrador y entregar de inmediato._ 💚`;
} else if (tipoNotif === 'reserva_pendiente') {
    const cliente = data.cliente_nombre || 'Sin nombre';
    const telefono = data.cliente_telefono || 'No proporcionado';
    const fecha = data.fecha || '';
    const hora = data.hora || '';
    const personas = data.personas || 2;
    mensaje = `📅 *SOLICITUD DE RESERVA PENDIENTE* 🪑\n----------------------------------\n👤 *Cliente:* ${cliente}\n📞 *Teléfono:* ${telefono}\n📆 *Fecha/Hora:* ${fecha} a las ${hora}\n👥 *Comensales:* ${personas} personas\n----------------------------------\n⚡ _Ingresa al Dashboard para aprobar o declinar la solicitud._ 🌱`;
} else {
    // Código original para compras
    const cliente = data.cliente?.nombre || "Sin nombre";
    const telefono = data.cliente?.telefono || "No proporcionado";
    const total = data.total || 0;
    const idOrden = data.orden_id || "000";

    let tipo = '🥡 Para Recoger en Tienda';
    if (data.tipo_entrega === 'delivery') {
        tipo = '🛵 Delivery a Domicilio';
    } else if (data.tipo_entrega === 'salon') {
        tipo = '🍽️ Consumo en Salón';
    }

    const filtradoItems = [];
    const itemsRaw = data.items || [];
    for (let i = 0; i < itemsRaw.length; i++) {
        if (itemsRaw[i] !== null && itemsRaw[i] !== undefined) {
            filtradoItems.push(itemsRaw[i]);
        }
    }

    const platosLineas = [];
    for (let i = 0; i < filtradoItems.length; i++) {
        const it = filtradoItems[i];
        const nombrePlato = it.plato || 'Plato sin nombre';
        const precio = item?.precio_unitario || it.precio_unitario || 0;
        const cantidad = it.cantidad || 1;
        platosLineas.push(`- ${cantidad}x ${nombrePlato} (S/. ${precio.toFixed(2)})`);
    }

    const textoPlatos = platosLineas.join('\n') || "- Sin productos específicos";

    // Construimos el mensaje final
    mensaje = `🛍️ *NUEVA COMPRA RECIBIDA! (#${idOrden.split('-')[0]})*\n----------------------------------\n📍 *Canal:* ${tipo}\n👤 *Cliente:* ${cliente}\n📞 *Teléfono:* ${telefono}\n\n📦 *Detalle del Pedido:*\n${textoPlatos}\n----------------------------------\n💰 *Monto Total:* S/. ${total.toFixed(2)}\n\n⚡ _Por favor, cambiar el estado a \"En Cocina\" en el Dashboard._ 🌱`;
}

// Extracción dinámica del destinatario
const destinatarioFinal = data.restaurante_grupo_whatsapp || data.restaurante_telefono;

return [{ json: {
        number: destinatarioFinal, 
        text: mensaje
    } }];

const output = $json.texto_ia || $json.output || "";
const problemas = [];

// Patrones técnicos reales que debemos bloquear
const fugasReales = [
  /supabase/i, 
  /postgresql/i, 
  /fetch failed/i, 
  /node_modules/i, 
  /ECONNREFUSED/i, 
  /\[object Object\]/i,
  /undefined/i
];

for (const patron of fugasReales) {
  if (patron.test(output)) { 
    problemas.push("🔴 fuga_tecnica"); 
    break; 
  }
}

if (output.trim().length === 0) {
  problemas.push("🔴 respuesta_vacia");
}

const severidad = problemas.some(p => p.includes("🔴")) ? "CRITICO" : "WARNING";

if (problemas.length > 0) {
  return [{ 
    json: { 
      output: "¡Uy, perdona! Me distraje un segundo con mis plantas 🌿 ¿Me podrías repetir eso? Quiero asegurarme de darte el mejor consejo 💛",
      _paso: "fallback",
      _guardia: {
          problemas: problemas,
          severidad: severidad,
          outputOriginal: output.substring(0, 1000),
          timestamp: new Date().toISOString()
        }
    }
  }];
}

return [{ 
  json: { 
    ...$json,
    output: output, 
    _paso: "ok" 
  } 
}];

const guardia = $json._guardia;
