const originales = $items("Separar Platos");

// 2. Unimos el texto bonito de la IA con los datos originales incluyendo ingredientes y etiquetas
return $input.all().map((item, index) => {
  const original = originales[index].json;

  // Convertimos las etiquetas dietéticas a texto legible si existen
