    ? original.etiquetas_dieteticas.join(', ') 
    : 'Ninguna';

  return {
    json: {
      // Usamos pageContent para incluir toda la metadata útil para búsquedas semánticas y de alérgenos
      pageContent: `Plato: ${original.nombre}. Categoría: ${original.categoria}. Descripción: ${item.json.message.content}. Ingredientes: ${original.ingredientes || 'No especificados'}. Etiquetas dietéticas: ${etiquetas}.`,

      // Filtros en la carpeta metadata
      metadata: {
        restaurante_telefono: original.telefono,
