const webhookData = $('Webhook3').item.json.body;
const inputClientes = $('🔍 Buscar Clientes (Supabase RPC)').item.json;
const clientes = Array.isArray(inputClientes) ? inputClientes : [inputClientes];
const restaurante = $('🛡️ Firewall de Salida (Guardrails IA)1').item.json[0] || {};

const plantilla = webhookData.plantilla_mensaje;
const promocion = webhookData.promocion || 'un descuento especial';
const dia = webhookData.dia || 'hoy';
const nombreRestaurante = restaurante.nombre || 'Suna Gourmet';

const hora = new Date().getHours();
let saludo = '¡Hola!';
if (hora >= 6 && hora < 12) saludo = '¡Buenos días!';
else if (hora >= 12 && hora < 18) saludo = '¡Buenas tardes!';
else saludo = '¡Buenas noches!';

const results = [];

for (const cliente of clientes) {
  if (cliente.en_cooldown === true) {
    continue;
  }

  let msg = plantilla
    .replace(/{nombre}/gi, cliente.nombre || 'cliente')
    .replace(/{dia}/gi, dia)
    .replace(/{promocion}/gi, promocion)
    .replace(/{plato_favorito}/gi, cliente.plato_favorito || 'nuestros platos')
    .replace(/{dias_inactivo}/gi, cliente.dias_inactivo || '15')
    .replace(/{saludo_temporal}/gi, saludo)
    .replace(/{sucursal_cercana}/gi, cliente.sucursal_cercana || 'nuestra sede')
    .replace(/{nombre_restaurante}/gi, nombreRestaurante)
    .replace(/{opt_out}/gi, '');

  let telf = (cliente.telefono || '').replace(/\D/g, '');
  if (telf && !telf.startsWith('51') && telf.length === 9) {
    telf = '51' + telf;
  }

  if (!telf) continue;

  results.push({
    json: {
      telefono: telf,
      mensaje: msg,
      cliente_id: cliente.id,
      nombre_cliente: cliente.nombre
    }
  });
}

return results;

let textoFinal = $('AI Agent').item.json.output || "";
