// Calcular tiempo humano de respuesta y tipeo
const texto = $json.output || $json.texto_ia || '';
const charCount = texto.length;

// Velocidad de tipeo humana: ~35-40ms por caracter
// Delay cognitivo de lectura y formulación: 1200ms
// Jitter aleatorio: 200ms a 700ms
const jitter = Math.floor(Math.random() * 500) + 200;
let typingDurationMs = Math.round(1200 + (charCount * 35) + jitter);

// Acotar entre 1.8 segundos y 6.5 segundos para no frustrar la velocidad de atención
if (typingDurationMs < 1800) typingDurationMs = 1800;
if (typingDurationMs > 6500) typingDurationMs = 6500;

const delaySeconds = Math.round(typingDurationMs / 1000);

return [{
  json: {
    ...$json,
    typing_duration_ms: typingDurationMs,
    delay_seconds: delaySeconds
  }
}];
